	.leaf {
		animation: forest-leaf 3.6s steps(1, end) infinite;
		animation-play-state: paused;
	}

	.sprout {
		animation: forest-sprout 5.2s steps(1, end) infinite;
		animation-delay: -1.7s;
		animation-play-state: paused;
	}

	.animated .leaf,
	.animated .sprout {
		animation-play-state: running;
	}

	@keyframes forest-leaf {
		0%,
		100% {
			transform: translateX(0);
		}
		50% {
			transform: translateX(1px);
		}
	}

	@keyframes forest-sprout {
		0%,
		100% {
			transform: translateX(0);
		}
		35% {
			transform: translateX(1px);
		}
		70% {
			transform: translateX(-1px);
		}
	}

	@media (prefers-reduced-motion: reduce) {
		.leaf,
		.sprout {
			animation: none;
		}
	}
